    'opml-outline-builder':{fields:[I('title','OPML 標題','ToolHub 訂閱清單'),S('mode','輸入格式','feeds',[['feeds','Feed 清單'],['outline','縮排大綱']]),T('input','清單內容','ToolHub Blog | https://example.com/feed.xml | https://example.com/\nTech News | https://news.example.com/rss | https://news.example.com/','Feed：名稱 | XML URL | 網站；大綱：使用空白縮排')],run:v=>{let body;if(v.mode==='feeds')body=lines(req(v.input)).filter(Boolean).map((line,i)=>{const [text,xmlUrl,htmlUrl]=line.split('|').map(x=>x.trim());if(!xmlUrl)throw new Error(`第 ${i+1} 行缺少 Feed URL`);return`    <outline type="rss" text="${xmlEscape(text)}" title="${xmlEscape(text)}" xmlUrl="${xmlEscape(xmlUrl)}"${htmlUrl?` htmlUrl="${xmlEscape(htmlUrl)}"`:''}/>`}).join('\n');else{const rows=lines(req(v.input)).filter(Boolean),stack=[],out=[];rows.forEach(line=>{const indent=Math.floor(line.match(/^\s*/)[0].length/2),text=line.trim();while(stack.length>indent)out.push(`${'    '.repeat(stack.length+1)}</outline>`),stack.pop();out.push(`${'    '.repeat(indent+1)}<outline text="${xmlEscape(text)}">`);stack.push(text)});while(stack.length)out.push(`${'    '.repeat(stack.length+1)}</outline>`),stack.pop();body=out.join('\n')}const xml=`<?xml version="1.0" encoding="UTF-8"?>\n<opml version="2.0">\n  <head><title>${xmlEscape(v.title)}</title></head>\n  <body>\n${body}\n  </body>\n</opml>`;return R(xml,'OPML 已產生',[['模式',v.mode],['項目',lines(v.input).filter(Boolean).length]],{filename:'subscriptions.opml',mime:'text/x-opml'})}},
    'rss-feed-builder':{fields:[I('title','頻道標題','ToolHub 更新'),I('link','頻道網址','https://toolhuben.com/'),I('description','頻道描述','免費、隱私友善的瀏覽器工具更新'),I('language','語言','zh-TW'),T('items','文章資料','新工具上線 | https://toolhuben.com/about/ | 2026-08-21 | ToolHub 新增更多純前端工具。\n使用指南 | https://toolhuben.com/ | 2026-08-20 | 認識本機處理的優點。','每行：標題 | URL | 日期 | 摘要')],run:v=>{const items=lines(req(v.items)).filter(Boolean).map((line,i)=>{const [title,link,date,...description]=line.split('|').map(x=>x.trim());if(!title||!link)throw new Error(`第 ${i+1} 行缺少標題或 URL`);const d=new Date(date);if(Number.isNaN(+d))throw new Error(`第 ${i+1} 行日期錯誤`);return`    <item>\n      <title>${xmlEscape(title)}</title>\n      <link>${xmlEscape(link)}</link>\n      <guid isPermaLink="true">${xmlEscape(link)}</guid>\n      <pubDate>${d.toUTCString()}</pubDate>\n      <description>${xmlEscape(description.join(' | '))}</description>\n    </item>`}),out=`<?xml version="1.0" encoding="UTF-8"?>\n<rss version="2.0">\n  <channel>\n    <title>${xmlEscape(v.title)}</title>\n    <link>${xmlEscape(v.link)}</link>\n    <description>${xmlEscape(v.description)}</description>\n    <language>${xmlEscape(v.language)}</language>\n${items.join('\n')}\n  </channel>\n</rss>`;return R(out,'RSS Feed 已產生',[['文章',items.length],['語言',v.language]],{filename:'feed.xml',mime:'application/rss+xml'})}},
    'social-share-link-builder':{fields:[I('url','分享網址','https://toolhuben.com/'),I('title','標題','ToolHub 免費線上工具'),T('summary','摘要','所有資料都在瀏覽器本機處理。'),C('html','同時產生 HTML 連結',true)],run:v=>{const u=encodeURIComponent(req(v.url)),t=encodeURIComponent(v.title),s=encodeURIComponent(v.summary),links={Facebook:`https://www.facebook.com/sharer/sharer.php?u=${u}`,X:`https://twitter.com/intent/tweet?url=${u}&text=${t}`,LinkedIn:`https://www.linkedin.com/sharing/share-offsite/?url=${u}`,LINE:`https://social-plugins.line.me/lineit/share?url=${u}`,Email:`mailto:?subject=${t}&body=${s}%0A${u}`},out=Object.entries(links).map(([name,url])=>`${name}: ${url}`).join('\n')+(v.html?'\n\n'+Object.entries(links).map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener">分享到 ${name}</a>`).join('\n'):'');return R(out,'社群分享連結已產生',[['平台',Object.keys(links).length],['HTML',v.html?'包含':'不包含']],{filename:'share-links.txt'})}},
    'wifi-qr-payload-builder':{fields:[I('ssid','Wi-Fi 名稱 SSID','ToolHub Guest'),I('password','密碼','safe-password-2026'),S('security','安全類型','WPA',[['WPA','WPA／WPA2／WPA3'],['WEP','WEP'],['nopass','無密碼']]),C('hidden','隱藏網路',false)],run:v=>{const esc=x=>String(x).replace(/([\\;,:"])/g,'\\$1'),password=v.security==='nopass'?'':v.password;if(v.security!=='nopass'&&!password)throw new Error('加密網路必須輸入密碼');const out=`WIFI:T:${v.security};S:${esc(req(v.ssid))};P:${esc(password)};H:${v.hidden?'true':'false'};;`;return R(`${out}\n\n將上方 Payload 貼到 ToolHub QR Code 產生器即可製作圖碼。`,'Wi-Fi QR Payload 已產生',[['安全',v.security],['隱藏網路',v.hidden?'是':'否'],['字元',out.length]],{filename:'wifi-qr-payload.txt'})}},
    'vcard-parser':{fields:[T('input','vCard 內容','BEGIN:VCARD\nVERSION:4.0\nFN:王小明\nORG:ToolHub\nTEL;TYPE=cell:+886912345678\nEMAIL;TYPE=work:hello@example.com\nADR;TYPE=work:;;信義路 1 號;台北市;;;台灣\nEND:VCARD')],run:v=>{const cards=req(v.input).split(/BEGIN:VCARD/i).slice(1).map(x=>x.split(/END:VCARD/i)[0]),unesc=x=>x.replace(/\\n/gi,'\n').replace(/\\([,;\\])/g,'$1'),parsed=cards.map((card,index)=>{const out={index:index+1,phones:[],emails:[],addresses:[],extra:{}};lines(card.replace(/\r?\n[ \t]/g,'')).forEach(line=>{const pos=line.indexOf(':');if(pos<0)return;const left=line.slice(0,pos),value=unesc(line.slice(pos+1)),[rawName,...params]=left.split(';'),name=rawName.toUpperCase(),entry={value,params};if(name==='FN')out.name=value;else if(name==='ORG')out.organization=value;else if(name==='TEL')out.phones.push(entry);else if(name==='EMAIL')out.emails.push(entry);else if(name==='ADR')out.addresses.push({...entry,parts:value.split(';')});else if(!['VERSION','N'].includes(name))out.extra[name]=value});return out});return R(JSON.stringify(parsed,null,2),'vCard 解析完成',[['聯絡人',parsed.length],['電話',parsed.reduce((s,x)=>s+x.phones.length,0)],['Email',parsed.reduce((s,x)=>s+x.emails.length,0)]],{filename:'contacts.json',mime:'application/json'})}}
